#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

static int tests_run = 0;
static int tests_fail = 0;

#define FAIL(msg) do { \
    printf("FAIL: %s at line %d\n", msg, __LINE__); \
    tests_fail++; \
} while(0)

#define CHECK(cond, msg) do { \
    tests_run++; \
    if (!(cond)) { FAIL(msg); } else { printf("PASS: %s\n", msg); } \
} while(0)

int main(void)
{
    /* --- 1. NULL / edge cases --- */
    tests_run++;

    rb_destroy(NULL); /* should not crash */

    CHECK(rb_create(0) == NULL, "rb_create(0) returns NULL");

    /* capacity == 1 must work */
    ringbuf_t *one = rb_create(1);
    CHECK(one != NULL, "rb_create(1) succeeds");
    if (!one) return 2;

    /* --- 2. Write and read with no wrap --- */
    uint8_t data[] = {10, 20, 30};
    size_t w = rb_write(one, data, 3);
    CHECK(w == 1, "write 3 bytes into cap-1 buffer writes only 1");

    uint8_t out[4];
    size_t r = rb_read(one, out, 4);
    CHECK(r == 1 && out[0] == 10u, "read gets the one written byte (10)");

    /* --- 3. Write and read fill/empty --- */
    ringbuf_t *rb = rb_create(4);
    CHECK(rb != NULL, "create cap-4 buffer");
    if (!rb) return 2;

    w = rb_write(rb, (uint8_t[]){1, 2, 3}, 3);
    CHECK(w == 3 && rb_size(rb) == 3, "write 3 into cap-4: wrote=3, size=3");

    uint8_t buf_out[4];
    r = rb_read(rb, buf_out, 3);
    CHECK(r == 3 && memcmp(buf_out, (uint8_t[]){1,2,3}, 3) == 0,
          "read 3 returns {1,2,3}");

    r = rb_read(rb, buf_out, 4);
    CHECK(r == 0 && rb_size(rb) == 0, "read from empty buffer returns 0");

    /* --- 4. Wrap-around on write + read --- */
    w = rb_write(rb, (uint8_t[]){10, 20}, 2);       /* buf: [10,20] at start */
    CHECK(w == 2, "write 2 bytes");
    CHECK(rb_size(rb) == 4, "size == capacity after write fills it");

    w = rb_write(rb, (uint8_t[]){30}, 1);            /* cap-full: should write 0? No, size==cap -> returns 0 */
    /* Actually size is 4 which equals capacity, so this writes 0 */
    if (w == 0)
        w = rb_write(rb, (uint8_t[]){30}, 1);

    /* Let's try a more classic wrap scenario: write some, read some, then write past end */
    ringbuf_t *rb2 = rb_create(4);
    CHECK(rb2 != NULL, "create second cap-4 buffer");
    if (!rb2) return 2;

    w = rb_write(rb2, (uint8_t[]){97, 98, 99}, 3);  /* [a,b,c] */
    CHECK(w == 3, "write 3 bytes");

    uint8_t rbuf[4];
    r = rb_read(rb2, rbuf, 2);                       /* read 'a','b', tail wraps to 0 */
    CHECK(r == 2 && rbuf[0] == 'a' && rbuf[1] == 'b', "read a,b from cap-4 ringbuf");

    w = rb_write(rb2, (uint8_t[]){ 120, 121}, 2);  /* 'x'\u003d120, 'y'\u003d121 */
    CHECK(w == 2, "write after partial read");

    uint8_t wrap_test_out[4];
    r = rb_read(rb2, wrap_test_out, 4);
    CHECK(r == 3 && wrap_test_out[0] == 'c' && wrap_test_out[1] == 120 && wrap_test_out[2] == 121,
          "read wraps correctly: c,x,y");

    /* --- 5. Peek (non-destructive) --- */
    ringbuf_t *rb3 = rb_create(4);
    uint8_t peek_buf[2];
    rb_write(rb3, (uint8_t[]){42, 99}, 2);
    r = rb_peek(rb3, peek_buf, 2);
    CHECK(r == 2 && peek_buf[0] == 42 && peek_buf[1] == 99, "peek gets first 2 bytes");
    CHECK(rb_size(rb3) == 2, "peek does not change size after peek");

    /* --- 6. Write larger than free space --- */
    ringbuf_t *rb4 = rb_create(4);
    rb_write(rb4, (uint8_t[]){1}, 1);                 /* one byte stored */
    w = rb_write(rb4, (uint8_t[]){0}, 100);          /* should write 3, not 4 (only 3 free) */
    CHECK(w == 3, "big write into small ringbuf: writes fitting bytes only");

    /* --- 7. Clear --- */
    rb_write(rb4, (uint8_t[]){A, B}, 2);             /* overwrite with A,B */
    rb_clear(rb4);
    CHECK(rb_size(rb4) == 0 && rb_capacity(rb4) == 4, "clear makes empty buffer");

    /* --- 8. rb_capacity and NULL-safe size --- */
    CHECK(rb_capacity(NULL) == 0, "rb_capacity(NULL) returns 0");
    CHECK(rb_size(NULL) == 0, "rb_size(NULL) returns 0");

    printf("\n===== Results =====\n");
    printf("Tests run: %d\n", tests_run);
    printf("Failures:  %d\n", tests_fail);

    rb_destroy(one);
    rb_destroy(rb);
    rb_destroy(rb2);
    rb_destroy(rb3);
    rb_destroy(rb4);

    return tests_fail > 0 ? 1 : 0;
}

